sys_script_fix.script:
setParentLocation();

function setParentLocation() {
    WPLogger.info('setParentLocation', 'Starting upgrade fix script to set Parent for WP Location');
    var wpLocationGr = new GlideRecord(WPConstants.TABLES.WORKPLACE_LOCATION);
    wpLocationGr.addNullQuery('parent');
    wpLocationGr.addQuery('sys_class_name', '!=', WPConstants.TABLES.REGION);
    wpLocationGr.setWorkflow(false);
    wpLocationGr.query();

    while (wpLocationGr.next()) {
        var childLocationGr = new GlideRecord(wpLocationGr.sys_class_name.toString());
        childLocationGr.get(wpLocationGr.getUniqueValue());
        new WPLocationUtils().setParentLocation(childLocationGr);
        childLocationGr.update();
    }

    WPLogger.info('setParentLocation', 'Finishing upgrade fix script to set Parent for WP Location');
}
